from lib import Buku,ayat,E
from isi_b import petak
M='muafakatcare.my'
def e7():
    b=Buku('menjaga-orang-tersayang-yang-terlantar','Menjaga Orang Tersayang yang Terlantar','Panduan asas untuk penjaga di rumah')
    b.teks('Untuk anda yang menjaga','Menjaga ibu, ayah atau pasangan yang terlantar ialah kerja yang berat dan mulia. Panduan ini mengumpulkan perkara asas yang selalu ditanya oleh keluarga yang meminjam katil hospital daripada kami.','<div class="kotak"><b>Penting:</b> eBook ini panduan umum, bukan nasihat perubatan. Ikut arahan doktor, jururawat atau ahli fisioterapi yang merawat pesakit anda. Jika ragu, tanya mereka dahulu.</div>',eyebrow='Pengenalan')
    b.teks('Menyediakan bilik',['Letakkan katil supaya penjaga boleh sampai dari <b>kedua-dua sisi</b>.','Pastikan bilik terang pada waktu siang dan ada pengudaraan yang baik.','Simpan barang harian dalam jangkauan: tisu basah, lampin, sarung tangan, losen, air minuman.','Sediakan loceng atau telefon supaya pesakit boleh memanggil.','Kunci roda katil setiap kali selepas mengalihkannya.','Naikkan palang sisi katil apabila pesakit ditinggalkan seorang.'],eyebrow='Persediaan')
    b.teks('Mengelak luka tekanan','Luka tekanan (kudis tekanan) berlaku apabila kulit ditekan terlalu lama di tempat yang sama, biasanya di tulang punggung, tumit, pinggul dan siku.',['<b>Ubah posisi dengan kerap.</b> Amalan biasa ialah setiap dua jam, tetapi ikut nasihat jururawat untuk pesakit anda.','Gunakan bantal untuk menyokong dan mengelak tulang bertemu tulang, contohnya di antara lutut.','Pastikan cadar tegang, kering dan tiada lipatan atau serpihan makanan.','Periksa kulit setiap hari ketika memandikan.'],'<div class="kotak"><b>Dapatkan nasihat segera</b> jika ternampak kulit kemerahan yang tidak hilang, melepuh, terbuka atau berbau.</div>',eyebrow='Penjagaan kulit')
    b.teks('Kebersihan harian',['<b>Mandi lap:</b> guna air suam; lap satu bahagian pada satu masa dan tutup bahagian lain supaya pesakit tidak kesejukan dan terjaga maruahnya.','<b>Mulut:</b> bersihkan gigi, gusi dan lidah sekurang-kurangnya dua kali sehari.','<b>Lampin:</b> tukar segera apabila basah atau kotor; bersihkan dari depan ke belakang dan keringkan kulit.','<b>Tangan penjaga:</b> basuh sebelum dan selepas setiap urusan.','Beritahu pesakit apa yang anda akan lakukan sebelum menyentuhnya, walaupun dia kelihatan tidak sedar.'],eyebrow='Kebersihan')
    b.teks('Makan dan minum',['Dudukkan pesakit setegak yang boleh semasa makan, dan kekalkan begitu seketika selepas makan.','Suap sedikit demi sedikit; tunggu sehingga ditelan sebelum suapan seterusnya.','Ikut tekstur makanan dan minuman yang dinasihatkan oleh pihak hospital.','Catat berapa banyak pesakit makan dan minum setiap hari.'],'<div class="kotak"><b>Berhenti menyuap dan dapatkan bantuan</b> jika pesakit batuk berterusan, tercekik, suaranya berubah menjadi basah, atau sukar bernafas. Bagi pesakit yang menggunakan tiub makanan, ikut sepenuhnya arahan jururawat.</div>',eyebrow='Pemakanan')
    b.teks('Solat dan ibadah pesakit','Islam memberi keringanan kepada orang sakit. Selagi akal masih waras, solat dilakukan mengikut kemampuan.',['Solat boleh dilakukan secara duduk, dan jika tidak mampu, secara berbaring dengan isyarat.','Jika tidak boleh menggunakan air, atau air memudaratkan, pesakit boleh bertayamum.','Bantu pesakit mengetahui masuk waktu solat dan arah kiblat.','Perdengarkan bacaan Al-Quran dan zikir; ajak pesakit berdoa.'],'<p class="kecil">Untuk keadaan khusus seperti pesakit yang memakai lampin, beg kencing atau tidak sedar, rujuk ustaz atau pegawai agama hospital.</p>',eyebrow='Ibadah')
    b.teks('Jaga diri anda juga','Penjaga yang keletihan tidak dapat menjaga dengan baik. Menjaga diri bukan mementingkan diri.',['Minta ahli keluarga bergilir, walaupun beberapa jam seminggu.','Tidur dan makan mengikut waktu sedaya mungkin.','Angkat pesakit dengan teknik yang betul; minta ditunjukkan oleh ahli fisioterapi. Jangan angkat seorang diri jika berat.','Luangkan masa untuk solat, berehat dan bercakap dengan seseorang.'],'<div class="kotak"><b>Tanda anda perlukan bantuan:</b> sukar tidur berpanjangan, cepat marah, rasa putus asa, atau sakit belakang yang berterusan. Berbincanglah dengan keluarga dan dapatkan nasihat di klinik.</div>',eyebrow='Untuk penjaga')
    b.teks('Bila perlu dapatkan rawatan segera','Hubungi klinik, hospital atau talian kecemasan 999 jika pesakit:',['Sukar bernafas, atau bibir kebiruan','Demam tinggi, menggigil atau keliru secara tiba-tiba','Tidak sedarkan diri atau sukar dikejutkan','Sakit dada, atau lemah sebelah badan secara tiba-tiba','Tidak membuang air kecil untuk tempoh yang lama','Mempunyai luka yang bernanah, berbau atau merebak'],'Simpan nombor klinik, hospital dan ahli keluarga terdekat di tempat yang mudah dilihat.',eyebrow='Kecemasan')
    b.teks('Catatan harian penjaga','<table><tr><th>Perkara</th><th>Pagi</th><th>Petang</th><th>Malam</th></tr>'+''.join(f'<tr><td>{x}</td><td></td><td></td><td></td></tr>' for x in ['Ubah posisi','Makan / minum','Ubat','Tukar lampin','Periksa kulit','Kebersihan mulut'])+'</table><p>Catatan untuk doktor atau jururawat:</p><div class="garis"></div><div class="garis"></div><div class="garis"></div>',eyebrow='Boleh dicetak')
    b.tutup('Perlukan katil hospital?','Muafakat Care meminjamkan katil hospital wakaf tanpa caj kepada pesakit terlantar di kawasan Muar, tertakluk kepada kekosongan. Katil dihantar dan dipasang oleh sukarelawan.',M+'/program/wakaf-katil','Mohon atau wakaf katil hospital')
    return b
def e8():
    b=Buku('didik-anak-suka-memberi','Didik Anak Suka Memberi','15 aktiviti keluarga untuk menanam sifat pemurah')
    b.teks('Kenapa mula dari kecil?','Sifat pemurah tidak muncul sendiri apabila dewasa. Ia dibina melalui apa yang anak lihat dan lakukan berulang kali. Anak yang biasa memberi akan membesar dengan rasa cukup dan prihatin.','Tiga prinsip:',['<b>Tunjuk, bukan suruh.</b> Biar anak nampak anda memberi.','<b>Biar anak yang menyerahkan.</b> Rasa memberi lebih melekat daripada cerita tentangnya.','<b>Puji usaha, bukan jumlah.</b>'],eyebrow='Pengenalan')
    b.teks('Tabung tiga balang','Sediakan tiga balang atau tabung dan labelkan:',['<b>Belanja</b>: untuk kehendak sekarang','<b>Simpan</b>: untuk sesuatu yang dihajati','<b>Beri</b>: untuk orang lain'],'Setiap kali anak menerima wang saku atau duit raya, biar dia sendiri membahagikannya. Tiada nisbah yang wajib; mulakan dengan apa yang anak selesa, kemudian bincang.','<div class="biru">Setiap hujung bulan, buka balang <b>Beri</b> bersama-sama dan biar anak memilih ke mana ia disalurkan.</div>',eyebrow='Asas')
    b.teks('Umur 4 hingga 6 tahun',['<b>1. Pilih mainan untuk diberi.</b> Anak memilih sendiri satu mainan yang masih elok.','<b>2. Tabung masjid.</b> Biar anak yang memasukkan wang.','<b>3. Kongsi makanan.</b> Hantar sepinggan kuih ke rumah jiran bersama anak.','<b>4. Beri minum haiwan.</b> Sediakan bekas air untuk kucing atau burung.','<b>5. Ucap terima kasih.</b> Lukis kad untuk seseorang yang membantu keluarga.'],eyebrow='Aktiviti 1–5')
    b.teks('Umur 7 hingga 9 tahun',['<b>6. Bungkus bersama.</b> Bantu membungkus barang dapur untuk disedekahkan.','<b>7. Sedekah Jumaat.</b> Anak mengira dan menyediakan wang setiap Khamis malam.','<b>8. Ziarah.</b> Bawa anak menziarahi datuk, nenek atau jiran warga emas.','<b>9. Kemas dan derma.</b> Asingkan pakaian yang sudah tidak muat tetapi masih elok.','<b>10. Bantu di rumah tanpa upah.</b> Ajar bahawa tenaga juga sedekah.'],eyebrow='Aktiviti 6–10')
    b.teks('Umur 10 hingga 12 tahun',['<b>11. Pilih kempen.</b> Anak membaca tentang beberapa kempen dan memilih satu untuk disokong.','<b>12. Projek kecil.</b> Jual kuih atau kraf, sebahagian hasil disedekahkan.','<b>13. Ajar adik atau rakan.</b> Ilmu yang dikongsi juga pemberian.','<b>14. Catat syukur.</b> Tulis tiga perkara yang disyukuri setiap malam selama seminggu.','<b>15. Turun padang.</b> Sertai aktiviti sukarelawan yang sesuai bersama ibu bapa.'],eyebrow='Aktiviti 11–15')
    a,ms,lab=ayat('76:8-9'); b.hal(f'<h2>Untuk dibaca bersama</h2><div class="arab pjg">{E(a)}</div><p class="terj">“{E(ms)}”</p><p class="ruj">{lab}</p><p>Tanya anak: Kenapa mereka memberi makanan yang mereka sendiri suka? Kenapa mereka tidak mahu ucapan terima kasih?</p>','Sebelum tidur')
    b.hal('<h2>Carta bintang 30 hari</h2><p>Warnakan satu petak setiap kali anak melakukan satu kebaikan untuk orang lain.</p>'+petak(30)+'<p>Kebaikan yang paling saya suka bulan ini:</p><div class="garis"></div><div class="garis"></div>','Boleh dicetak')
    b.teks('Pesanan untuk ibu bapa',['Jangan paksa. Anak yang dipaksa memberi akan belajar bahawa memberi itu menyakitkan.','Jangan malukan anak di hadapan orang jika dia enggan.','Jaga maruah penerima; elak mengambil gambar wajah mereka.','Ceritakan ke mana pemberian itu pergi dan siapa yang terbantu.'],eyebrow='Peringatan')
    b.tutup('Beri bersama keluarga','Jadikan balang “Beri” keluarga anda sebahagian daripada kebaikan untuk keluarga yang memerlukan di Bakri dan Muar.',M+'/infak','Infak bersama Muafakat Care')
    return b
def e9():
    b=Buku('planner-ramadan-si-dermawan','Planner Ramadan Si Dermawan','30 hari merancang ibadah dan infak')
    b.hadis(1,'bukhari',3554,'Ibnu Abbas berkata: “Nabi ialah orang yang paling pemurah, dan Baginda lebih pemurah lagi pada bulan Ramadan ketika Jibril menemuinya. Jibril menemuinya pada setiap malam Ramadan untuk bertadarus Al-Quran dengannya. Sungguh, Rasulullah lebih pemurah dalam kebaikan daripada angin yang bertiup.”','Rancang kemurahan anda sebelum Ramadan bermula, supaya ia tidak bergantung pada baki wang.','Lebih pemurah pada bulan Ramadan')
    b.teks('Niat dan sasaran saya','<p>Tiga perkara yang saya mahu capai Ramadan ini:</p><div class="garis"></div><div class="garis"></div><div class="garis"></div><p style="margin-top:14px">Satu tabiat yang saya mahu tinggalkan:</p><div class="garis"></div><p style="margin-top:14px">Sasaran tilawah: <span style="display:inline-block;width:90px;border-bottom:1px solid #7281A8"></span></p>',eyebrow='Sebelum mula')
    b.teks('Bajet infak Ramadan','<table><tr><th>Perkara</th><th>Jumlah (RM)</th><th>Selesai</th></tr>'+''.join(f'<tr><td>{x}</td><td></td><td></td></tr>' for x in ['Sedekah harian (× 30 hari)','Juadah berbuka untuk orang lain','10 malam terakhir','Zakat fitrah (ikut kadar rasmi negeri)','Fidyah, jika ada','Sumbangan Syawal untuk keluarga memerlukan','<b>Jumlah</b>'])+'</table>','<p class="kecil">Zakat fitrah dan fidyah dibayar mengikut kadar dan saluran yang ditetapkan oleh pihak berkuasa agama negeri anda.</p>',eyebrow='Rancang')
    b.hadis(2,'tirmidhi',807,'Sesiapa yang memberi makan berbuka kepada orang yang berpuasa, dia mendapat pahala seperti orang itu, tanpa mengurangkan pahala orang yang berpuasa itu sedikit pun.','Tetapkan berapa orang yang ingin anda beri makan berbuka Ramadan ini.','Memberi makan berbuka')
    for m in range(3):
        rows=''.join(f'<tr><td>{i}</td><td></td><td></td><td></td><td></td></tr>' for i in range(m*10+1,m*10+11))
        b.hal(f'<h2>Ramadan {m*10+1} hingga {m*10+10}</h2><table><tr><th style="width:38px">Hari</th><th>Solat 5 waktu + tarawih</th><th>Tilawah (muka surat)</th><th>Sedekah</th><th>Satu kebaikan</th></tr>{rows}</table>'+('<div class="kotak"><b>10 malam terakhir:</b> sediakan infak untuk setiap malam lebih awal, supaya tidak terlepas malam yang paling utama.</div>' if m==2 else ''),'Jurnal harian')
    b.teks('Selepas Ramadan','<ul class="semak">'+''.join(f'<li>{x}</li>' for x in ['Zakat fitrah ditunaikan sebelum solat Aidilfitri','Puasa enam hari pada bulan Syawal','Meneruskan satu infak tetap','Meneruskan tilawah harian, walaupun satu muka surat','Menziarahi keluarga dan jiran'])+'</ul>','<p>Amalan Ramadan yang saya mahu kekalkan:</p><div class="garis"></div><div class="garis"></div>',eyebrow='Syawal')
    b.tutup('Ramadan yang memberi','Setiap Ramadan, Muafakat Care mengagihkan sumbangan barangan asas kepada keluarga yang memerlukan di sekitar Bakri dan Muar.',M+'/infak','Infak bersama Muafakat Care')
    return b
def e10():
    b=Buku('zakat-fidyah-sedekah-wakaf-apa-bezanya','Zakat, Fidyah, Sedekah, Wakaf: Apa Bezanya?','20 soalan yang selalu ditanya penyumbang')
    b.teks('Sepintas lalu','<table><tr><th></th><th>Hukum</th><th>Untuk siapa</th><th>Diurus oleh</th></tr><tr><td><b>Zakat</b></td><td>Wajib</td><td>Lapan golongan asnaf</td><td>Pihak berkuasa agama negeri</td></tr><tr><td><b>Fidyah</b></td><td>Wajib bagi yang berkenaan</td><td>Fakir dan miskin</td><td>Pihak berkuasa agama negeri</td></tr><tr><td><b>Sedekah / infak</b></td><td>Sunat</td><td>Sesiapa yang memerlukan</td><td>Sendiri atau melalui pertubuhan</td></tr><tr><td><b>Wakaf</b></td><td>Sunat</td><td>Manfaat umum yang berterusan</td><td>Pengurus wakaf</td></tr></table>','<div class="kotak"><b>Nota:</b> eBook ini panduan umum. Kadar, cara kiraan dan saluran rasmi zakat serta fidyah ditetapkan oleh Majlis Agama Islam negeri masing-masing dan boleh berubah setiap tahun.</div>',eyebrow='Ringkasan')
    S=[('Zakat',[('Siapakah lapan asnaf?','Fakir, miskin, amil, mualaf, hamba yang ingin merdeka (riqab), orang yang berhutang (gharimin), fi sabilillah dan ibnu sabil. Ini disebut dalam surah at-Taubah, ayat 60.'),('Bolehkah saya bayar zakat kepada NGO?','Di Malaysia, kutipan dan agihan zakat diuruskan oleh pihak berkuasa agama negeri. Bayarlah zakat melalui saluran rasmi negeri anda. Muafakat Care tidak mengutip zakat.'),('Apa beza zakat fitrah dan zakat harta?','Zakat fitrah wajib ke atas setiap Muslim pada bulan Ramadan sebelum solat Aidilfitri. Zakat harta dikenakan ke atas harta tertentu apabila cukup nisab dan haul.'),('Berapa kadarnya?','Rujuk kadar rasmi yang diumumkan oleh pihak berkuasa agama negeri anda pada tahun semasa.')]),
       ('Fidyah',[('Bila fidyah dikenakan?','Antaranya bagi orang yang tidak mampu berpuasa kerana tua atau sakit yang tiada harapan sembuh, dan beberapa keadaan lain yang dihuraikan oleh ulama.'),('Bagaimana mengiranya?','Secara umum, satu cupak makanan asasi bagi setiap hari yang ditinggalkan. Nilai dalam ringgit ditetapkan oleh pihak berkuasa agama negeri.'),('Ke mana fidyah dibayar?','Melalui saluran rasmi pihak berkuasa agama negeri, yang mengagihkannya kepada fakir dan miskin.')]),
       ('Sedekah dan infak',[('Adakah sedekah dan infak berbeza?','Infak biasanya merujuk kepada pemberian harta. Sedekah lebih luas: senyuman, tenaga dan kata-kata yang baik juga sedekah.'),('Adakah jumlah minimum?','Tiada. Yang diutamakan ialah keikhlasan dan berterusan.'),('Mana lebih baik, terang atau sembunyi?','Kedua-duanya baik, seperti dalam surah al-Baqarah ayat 271. Sedekah sembunyi lebih menjaga hati; sedekah terang boleh menjadi contoh.'),('Bolehkah bersedekah untuk orang yang telah meninggal?','Jumhur ulama berpandangan pahala sedekah sampai kepada si mati apabila diniatkan untuknya.'),('Bolehkah bersedekah ketika masih berhutang?','Menunaikan hutang yang wajib dibayar adalah lebih utama. Sedekah kecil yang tidak menjejaskan kemampuan membayar hutang masih boleh dilakukan.')]),
       ('Wakaf',[('Apa yang boleh diwakafkan?','Harta yang kekal zatnya dan boleh diambil manfaat berulang kali, seperti tanah, bangunan, peralatan dan mushaf.'),('Bolehkah berwakaf dengan wang?','Ya, melalui skim wakaf tunai yang diuruskan oleh pihak berkuasa atau institusi yang diberi kebenaran. Wang itu ditukar menjadi aset yang kekal.'),('Bolehkah wakaf ditarik balik?','Tidak. Setelah diwakafkan, harta itu bukan lagi milik pewakaf.')]),
       ('Tentang NGO',[('Bagaimana saya tahu sumbangan saya sampai?','Pilih pertubuhan yang melaporkan agihannya secara terbuka. Muafakat Care menerbitkan laporan di Papan Impak, dengan pautan kepada hebahan asal.'),('Bagaimana menyemak pertubuhan itu berdaftar?','Minta nombor pendaftaran dan semak dengan Jabatan Pendaftaran Pertubuhan Malaysia (ROS). Pertubuhan Kebajikan Muafakat Bakri berdaftar dengan nombor PPM-002-10-13032020.'),('Kenapa sumbangan mesti ke akaun pertubuhan?','Akaun atas nama pertubuhan boleh diaudit. Berhati-hati dengan permintaan sumbangan ke akaun peribadi.'),('Bolehkah saya memilih program?','Boleh. Gunakan pautan kempen yang berkenaan, atau nyatakan rujukan semasa membuat pindahan.'),('Adakah resit dikeluarkan?','Sumbangan melalui pautan rasmi menghasilkan resit transaksi secara automatik. Untuk pindahan bank, hubungi kami melalui WhatsApp.')])]
    n=0
    for tajuk,soal in S:
        isi=f'<h2>{tajuk}</h2>'
        for s,j in soal: n+=1; isi+=f'<h3>{n}. {s}</h3><p>{j}</p>'
        b.hal(isi,'Soal jawab')
    assert n==20,n
    b.tutup('Masih ada soalan?','Hubungi kami melalui WhatsApp di laman web. Untuk soalan hukum yang khusus, rujuk pejabat agama atau mufti negeri anda.',M+'/soalan-lazim','Soalan lazim Muafakat Care')
    return b
